  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "RISK-APPROPRIATE",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-002 through T-007 and T-009 through T-013 cover contracts, authorization, identity policies or protected dispatch and declare high risk. T-001 scoped regression integration and T-008 documentation/release delivery declare medium risk without adding cloud authority."
    },
    {
      "id": "HIGH-CRITICAL-EVIDENCE",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Every high-risk task's Done When requires failing tests committed before implementation, Red→Green evidence and a named independent reviewer verdict. No critical task is declared."
    },
    {
      "id": "TASK-SIZE",
      "result": "PASS",
      "severity": "Major",
      "finding": "Provider-local preparation, governed execution, observation, dispatch, dependency validation, packaging and host integration have separate task boundaries. Each task has four or five Done When bullets; no single-edit fragmentation is present."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "AC-001 through AC-012 and corresponding task criteria include removed anchors, unsupported owners, missing backup, digest mutation, denied authorization, replay/timeouts, destructive changes, unsupported profiles, stale observations, unsafe evidence and direct-entry denial. T-008 is documentation/release work."
    },
    {
      "id": "TEST-TYPE-MATCH",
      "result": "PASS",
      "severity": "Major",
      "finding": "Planned integration cases cross router/entry, authorization/executor, collector/reducer or installer/installed-entry boundaries. Local module cases are distinguished from real compile/synthesis, isolated host and live sandbox evidence; acceptance checks cite AC-001 through AC-014."
    },
    {
      "id": "ROLLBACK-PLAN",
      "result": "PASS",
      "severity": "Major",
      "finding": "Every high-risk task explicitly requires a documented and tested rollback procedure with hashes and baseline output. The shared rollback section requires task-owned restoration, disables defective cloud entry/workflows and prohibits destructive cloud rollback or historical ledger restoration."
    },
    {
      "id": "SCOPE-DISJOINT",
      "result": "PASS",
      "severity": "Major",
      "finding": "Shared routing tests are ordered T-004 → T-005 → T-011; execution tests T-003 → T-012 → T-013; verification tests T-006 → T-009 → T-010. Provider adapter extensions and final driver wiring also have transitive blocking relationships."
    },
    {
      "id": "DEPENDENCY-OVERLAP",
      "result": "FAIL",
      "severity": "Major",
      "finding": "tasks.md T-007 declares Blockers: T-010, but its packaging/install scope and Done When consume provider CLIs and shared validation, not T-010's dependency receipt validator or ordering helper. No T-010 output is identified as an installation prerequisite. This unnecessarily places independent packaging behind dependency orchestration and inflates the critical path; identify a concrete consumed artifact or replace the blocker with genuine packaging prerequisites."
    },
    {
      "id": "BUGFIX-DIAGNOSTIC-PATH",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001 Goal requires diagnosis of the historical stale-line failure before further fixes. Done When retains the exact failure log, investigates the section reference and runs the foundation regression command with removal, relocation, duplicate-heading and path-escape cases."
    }
  ],
  "findings": [
    {
      "check_id": "DEPENDENCY-OVERLAP",
      "severity": "Major",
      "task_id": "T-007",
      "finding": "tasks.md T-007 Blockers names T-010, whose output is a dependency receipt validator and ordering helper. T-007's plugin manifests, shared-validation installation and install/uninstall tests identify no dependency on that output. The spurious blocker unnecessarily serializes independent packaging behind orchestration work. Specify the actual consumed T-010 artifact or use genuine packaging prerequisites."
    }
  ]
